"""Turn SLO specs into Prometheus recording and alerting rules."""

from __future__ import annotations

from typing import Any

import yaml

from libs.core import naming
from tools.slo.models import SELECTOR_PATTERN, AvailabilitySli, SloSpec, SpecError
from tools.slo.profiles import PROFILES, BurnTier, Profile

HEADER = (
    "# GENERATED by `python -m tools.cli slo generate` from slo/{name}.yaml.\n"
    "# Do not edit: change the spec and regenerate. CI fails if this file is stale.\n"
)
AGENT_URL = "http://localhost:8080"
GRAFANA_SLO_DASHBOARD = "http://localhost:3000/d/relialoop-slo/slo-and-error-budget"


def format_number(value: float) -> str:
    """Render a number without float noise (`14.4`, `6`, `0.005`)."""
    return f"{value:.10g}"


def bucket_label(threshold: float) -> str:
    """The `le` label value prometheus_client emits for a bucket boundary."""
    return repr(float(threshold))


def with_matchers(selector: str, extra: list[str], suffix: str = "") -> str:
    """Add label matchers (and an optional metric-name suffix) to a selector."""
    match = SELECTOR_PATTERN.match(selector)
    if not match:
        raise SpecError(f"not a metric selector: {selector!r}")
    existing = match.group("matchers")
    matchers = ", ".join([*extra, *([existing] if existing else [])])
    return f"{match.group('name')}{suffix}{{{matchers}}}"


def profile_for(spec: SloSpec, override: str | None = None) -> Profile:
    """Alerting profile of a spec, or an explicit override (used by tests and docs)."""
    return PROFILES[override or spec.alerting.profile]


def budget_window(spec: SloSpec, profile: Profile) -> str:
    """Window over which the error budget is accounted."""
    return profile.budget_window or spec.window


def rate_windows(spec: SloSpec, profile: Profile) -> list[str]:
    """Alert windows plus the budget window, without duplicates."""
    windows = list(profile.windows)
    budget = budget_window(spec, profile)
    if budget not in windows:
        windows.append(budget)
    return windows


def error_ratio_expr(spec: SloSpec, window: str, buckets: tuple[float, ...]) -> str:
    """PromQL for the share of bad events over `window`."""
    service = [f'service="{spec.service}"']
    sli = spec.sli
    if isinstance(sli, AvailabilitySli):
        errors = with_matchers(sli.errors, service)
        total = with_matchers(sli.total, service)
        # `or vector(0)`: a service that never returned an error has no error
        # series at all; without it the ratio would be absent instead of 0.
        return f"(sum(rate({errors}[{window}])) or vector(0)) / sum(rate({total}[{window}]))"
    if sli.threshold_seconds not in buckets:
        raise SpecError(
            f"{spec.name}: threshold {sli.threshold_seconds}s is not a histogram bucket "
            f"(buckets: {', '.join(format_number(b) for b in buckets)})"
        )
    le = f'le="{bucket_label(sli.threshold_seconds)}"'
    fast = with_matchers(sli.histogram, [*service, le], "_bucket")
    total = with_matchers(sli.histogram, service, "_count")
    return f"1 - (sum(rate({fast}[{window}])) / sum(rate({total}[{window}])))"


def total_rate_expr(spec: SloSpec, window: str) -> str:
    """PromQL for valid events per second over `window`."""
    service = [f'service="{spec.service}"']
    sli = spec.sli
    selector = (
        with_matchers(sli.total, service)
        if isinstance(sli, AvailabilitySli)
        else with_matchers(sli.histogram, service, "_count")
    )
    return f"sum(rate({selector}[{window}]))"


def _recording_rules(
    spec: SloSpec, profile: Profile, buckets: tuple[float, ...]
) -> list[dict[str, Any]]:
    labels = {"slo": spec.name, "service": spec.service}
    selector = f'{{slo="{spec.name}"}}'
    budget = format_number(spec.error_budget)
    rules: list[dict[str, Any]] = [
        {
            "record": naming.OBJECTIVE,
            "expr": f"vector({format_number(spec.objective / 100)})",
            "labels": labels,
        }
    ]
    for window in rate_windows(spec, profile):
        rules.append(
            {
                "record": naming.sli_error_ratio(window),
                "expr": error_ratio_expr(spec, window, buckets),
                "labels": labels,
            }
        )
        rules.append(
            {
                "record": naming.sli_total_rate(window),
                "expr": total_rate_expr(spec, window),
                "labels": labels,
            }
        )
    for window in rate_windows(spec, profile):
        rules.append(
            {
                "record": naming.burn_rate(window),
                "expr": f"{naming.sli_error_ratio(window)}{selector} / {budget}",
                "labels": labels,
            }
        )
    rules.append(
        {
            "record": naming.ERROR_BUDGET_REMAINING,
            "expr": f"1 - {naming.burn_rate(budget_window(spec, profile))}{selector}",
            "labels": labels,
        }
    )
    return rules


def _alert_rule(spec: SloSpec, tier: BurnTier) -> dict[str, Any]:
    selector = f'{{slo="{spec.name}"}}'
    factor = format_number(tier.factor)
    expr = (
        f"{naming.burn_rate(tier.long_window)}{selector} > {factor}\n"
        f"and {naming.burn_rate(tier.short_window)}{selector} > {factor}\n"
        f"and {naming.sli_total_rate(tier.long_window)}{selector} "
        f"> {format_number(spec.alerting.min_traffic_rps)}"
    )
    threshold_pct = format_number(tier.factor * spec.error_budget * 100)
    return {
        "alert": naming.burn_alert(tier.tier),
        "expr": expr,
        "for": tier.for_duration,
        "labels": {
            "severity": tier.severity,
            "class": "symptom",
            "slo": spec.name,
            "service": spec.service,
            "sli_type": spec.sli.type,
            "burn": tier.tier,
            "owner": spec.alerting.owner,
        },
        "annotations": {
            "summary": (
                f"{spec.name}: error budget burning at more than {factor}x "
                f"({tier.long_window}/{tier.short_window} windows)"
            ),
            "description": (
                f"{spec.description}. Objective {format_number(spec.objective)}%. "
                f"The bad-event ratio exceeded {threshold_pct}% over both the last "
                f"{tier.long_window} and the last {tier.short_window}. {tier.meaning}"
            ),
            "runbook_url": f"{AGENT_URL}/runbooks/{spec.alerting.runbook}",
            "dashboard_url": f"{GRAFANA_SLO_DASHBOARD}?var-slo={spec.name}",
        },
    }


def build_rule_groups(
    spec: SloSpec, buckets: tuple[float, ...], profile_override: str | None = None
) -> dict[str, Any]:
    """Rule file content (as a dict) for one SLO."""
    profile = profile_for(spec, profile_override)
    # One group on purpose: rules in a group run in order within one evaluation,
    # so the alerts always see burn rates computed in the same cycle.
    return {
        "groups": [
            {
                "name": f"slo-{spec.name}",
                "rules": [
                    *_recording_rules(spec, profile, buckets),
                    *(_alert_rule(spec, tier) for tier in profile.tiers),
                ],
            }
        ]
    }


class _BlockDumper(yaml.SafeDumper):
    """Writes multi-line strings as block scalars and never emits YAML anchors."""

    def ignore_aliases(self, data: object) -> bool:
        return True


def _represent_str(dumper: yaml.SafeDumper, data: str) -> yaml.ScalarNode:
    style = "|" if "\n" in data else None
    return dumper.represent_scalar("tag:yaml.org,2002:str", data, style=style)


_BlockDumper.add_representer(str, _represent_str)


def render_rule_file(
    spec: SloSpec, buckets: tuple[float, ...], profile_override: str | None = None
) -> str:
    """YAML text of the rule file for one SLO."""
    body = yaml.dump(
        build_rule_groups(spec, buckets, profile_override),
        Dumper=_BlockDumper,
        sort_keys=False,
        width=1000,
    )
    return HEADER.format(name=spec.name) + body
